package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public class DjPlannerTest {
 private DjPlanner.Song song(String id,String artist,boolean favorite){return new DjPlanner.Song(id,"Faixa "+id,artist,60000,0,0,favorite);}
 @Test public void favoritesSmallLibrariesAndLimitsAreRespected(){List<DjPlanner.Song> songs=Arrays.asList(song("1","A",true),song("2","B",false));List<DjPlanner.Song> favorite=DjPlanner.build(songs,DjPlanner.Mode.FAVORITES,30,1,10000);assertEquals(1,favorite.size());assertEquals("1",favorite.get(0).id);assertEquals(2,DjPlanner.build(songs,DjPlanner.Mode.PERSONAL,30,1,10000).size());assertTrue(DjPlanner.build(songs,DjPlanner.Mode.PERSONAL,0,1,10000).isEmpty());assertTrue(DjPlanner.build(Collections.emptyList(),DjPlanner.Mode.PERSONAL,30,1,10000).isEmpty());List<DjPlanner.Song> large=new ArrayList<>();for(int i=0;i<100;i++)large.add(song(""+i,"Artista "+i,false));assertEquals(60,DjPlanner.build(large,DjPlanner.Mode.PERSONAL,100,1,10000).size());}
 @Test public void knownArtistsAreSpacedWhenAlternativesExist(){List<DjPlanner.Song> songs=new ArrayList<>();for(int i=0;i<18;i++)songs.add(song(""+i,"Artista "+(i%3),false));for(int seed=0;seed<30;seed++){List<DjPlanner.Song> queue=DjPlanner.build(songs,DjPlanner.Mode.PERSONAL,18,seed,10000);assertEquals(18,queue.size());for(int i=1;i<queue.size();i++)assertNotEquals(queue.get(i-1).artist,queue.get(i).artist);assertEquals(18,new HashSet<>(ids(queue)).size());}}
 @Test public void duplicateCopiesPreferFavoritesButDifferentVersionsRemain(){List<DjPlanner.Song> songs=Arrays.asList(new DjPlanner.Song("1","Canção","João",60000,0,0,false),new DjPlanner.Song("2","Cancao","Joao",61000,0,0,true),new DjPlanner.Song("3","Canção","João",120000,0,0,false),song("3","João",false));List<DjPlanner.Song> queue=DjPlanner.build(songs,DjPlanner.Mode.PERSONAL,30,1,10000);assertEquals(2,queue.size());assertTrue(ids(queue).contains("2"));assertTrue(ids(queue).contains("3"));assertFalse(ids(queue).contains("1"));}
 @Test public void missingMetadataDoesNotCollapseUnrelatedFiles(){List<DjPlanner.Song> songs=Arrays.asList(new DjPlanner.Song("1","Sem título","Artista desconhecido",60000,0,0,false),new DjPlanner.Song("2","Sem título","Artista desconhecido",60000,0,0,false));assertEquals(2,DjPlanner.build(songs,DjPlanner.Mode.PERSONAL,30,1,10000).size());}
 @Test public void preferencesAndHistoryInfluenceWeightsWithoutExcludingSongs(){long now=100L*86400000;DjPlanner.Song favorite=song("1","A",true),ordinary=song("2","B",false);assertTrue(DjPlanner.weight(favorite,DjPlanner.Mode.PERSONAL,now)>DjPlanner.weight(ordinary,DjPlanner.Mode.PERSONAL,now));DjPlanner.Song recent=new DjPlanner.Song("3","Recente","C",60000,30,now,false);assertTrue(DjPlanner.weight(ordinary,DjPlanner.Mode.REDISCOVER,now)>DjPlanner.weight(recent,DjPlanner.Mode.REDISCOVER,now));int favoritesFirst=0;Random seeds=new Random(7);for(int i=0;i<1000;i++)if(DjPlanner.build(Arrays.asList(favorite,ordinary),DjPlanner.Mode.PERSONAL,1,seeds.nextLong(),now).get(0).favorite)favoritesFirst++;assertTrue(favoritesFirst>700);assertTrue(favoritesFirst<950);}
 @Test public void sameSeedIsReproducibleAndInputIsUnchanged(){List<DjPlanner.Song> songs=Arrays.asList(song("1","A",false),song("2","B",false),song("3","C",false));assertEquals(ids(DjPlanner.build(songs,DjPlanner.Mode.PERSONAL,30,5,10000)),ids(DjPlanner.build(songs,DjPlanner.Mode.PERSONAL,30,5,10000)));assertEquals("1",songs.get(0).id);}
 private List<String> ids(List<DjPlanner.Song> songs){List<String> result=new ArrayList<>();for(DjPlanner.Song song:songs)result.add(song.id);return result;}
}
